let 종료중 = false;
async function shutdown(sig) {
  if (종료중) return;            // 중복 신호 방어(TERM 두 번 와도 한 번만)
  종료중 = true;
  server.close();               // ① 새 요청 차단
  const 타임아웃 = setTimeout(() => process.exit(1), 10000); // 상한 대기
  await 진행중요청_완료();        // ② 진행 요청 끝나길 대기
  await db.end(); await queue.close();  // ③ 자원 해제
  clearTimeout(타임아웃);
  process.exit(0);              // ④ 깨끗이 종료
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));
